ROOT = Path(__file__).resolve().parent

def icon(name):
    return f'<img class="ic" src="assets/{name}.svg" alt="">'

def button(label, kind='secondary', symbol='', extra=''):
    return f'<button class="btn {kind}" {extra}>{icon(symbol) if symbol else ""}<span class="btn-label">{label}</span></button>'

def header(title, detail=False, right='user'):
    return f'<header class="titlebar {"detail" if detail else ""}">{button("", "icon", "chevron-left", "aria-label=返回") if detail else ""}<h2>{title}</h2>{button("", "icon", right, "aria-label=页面操作")}</header>'

def nav(active=0):
    pairs=[('阅读','book-open'),('工具','wrench'),('DSH','message-circle'),('多媒体','images'),('网盘','cloud')]
    return '<nav class="bottomnav" aria-label="示例底部导航">'+''.join(f'<button class="{"active" if i==active else ""}" data-demo="导航保持原有五个入口"><span class="navicon">{icon(symbol)}</span>{title}</button>' for i,(title,symbol) in enumerate(pairs))+'</nav>'

def seg(items, selected=0):
    return '<div class="seg" role="group">'+''.join(f'<button class="{"selected" if i==selected else ""}" aria-pressed="{str(i==selected).lower()}">{text}</button>' for i,text in enumerate(items))+'</div>'

def search(placeholder):
    return f'<label class="search">{icon("search")}<input placeholder="{placeholder}" aria-label="{placeholder}"></label>'

def chips(items, selected=0):
    return '<div class="chiprow">'+''.join(f'<button class="chip {"selected" if i==selected else ""}" aria-pressed="{str(i==selected).lower()}"><span>{t}</span></button>' for i,t in enumerate(items))+'</div>'

def label(title, action=''):
    return f'<div class="section-label"><h3>{title}</h3>{button(action,"quiet") if action else ""}</div>'

def row(title, sub='', symbol='folder', action='', kind='icon'):
    accessible = f'aria-label="{action or "打开"+title}"'
    return f'<div class="row"><span class="tile">{icon(symbol)}</span><div class="copy"><b>{title}</b><p>{sub}</p></div>{button(action,kind,"chevron-right" if not action else "", accessible)}</div>'

def book(title, author, chapter, progress, status='已缓存到本地', warn=False):
    return f'<div class="book"><button style="border:0;background:none;padding:0" data-demo="封面进入详情；文字区域进入阅读" aria-label="查看{title}详情"><img class="book-cover" src="assets/book-cover.png" alt="图书默认封面"></button><div class="book-info"><h3>{title}</h3><p>{author} · {chapter}</p><span class="status {"warning" if warn else ""}">{icon("download" if warn else "check")}{status}</span><div class="progressline"><div class="track"><i style="width:{progress}%"></i></div><small>{progress}%</small></div></div></div>'

def frame(title, number, content, note, category, dark=False, reader=False):
    return f'<article class="device-wrap" data-category="{category}"><div class="canvas-caption"><b>{number} / {title}</b><span>390 × 844</span></div><div class="phone {"theme-dark" if dark else ""} {"reader" if reader else ""}">{content}</div><p class="screen-note">{note}</p></article>'

