def media_row(title, duration, tags):
    tag_list=''.join(f'<span class="media-tag">{tag}</span>' for tag in tags)
    thumbnail=f'<span class="media-thumbnail">{icon("play")}<span class="media-item-tags" aria-label="{title}的标签">{tag_list}</span></span>'
    return f'<article class="media-item"><div class="row">{thumbnail}<div class="copy"><b>{title}</b><p>{duration} · 音频文件</p></div>'+button('','icon','chevron-right',f'aria-label="打开{title}"')+'</div></article>'

