components+='</div></div><div class="two-col"><div class="panel"><h3>文字操作的统一基线</h3><p>16 / 22，Medium；横向 8，图文间距 6。相邻点击区间至少 8；空间不够收进更多菜单。</p><div class="bar">'+button('复制','quiet','copy')+button('刷新','quiet','refresh-cw')+button('更多','quiet','ellipsis')+'</div><div style="height:16px"></div><div class="bar"><b class="grow">所有订阅</b>'+button('全部已读','quiet')+'</div></div><div class="panel"><h3>选择，不伪装成提交</h3><p>分段导航用于切换视图；筛选标签用于缩小结果。选中状态包含文字或结构变化。</p>'+seg(['书架','书源','远程','本地','RSS'])+chips(['全部','在读','已读完'])+'</div></div><div class="panel"><h3>表单、反馈与危险确认</h3><div class="two-col"><div><label class="field-label" for="spec-name">输出文件名</label><input id="spec-name" class="field error" value="" placeholder="输入文件名" aria-invalid="true" aria-describedby="spec-error"><p id="spec-error" class="error-note">请输入文件名后再保存。</p><p class="helper" style="margin-top:8px">错误就近显示；禁用原因不能只靠置灰。</p></div><div><h3 style="margin-top:20px">清除本地缓存？</h3><p class="helper">阅读记录会保留。再次打开时需要重新下载。</p><div class="bar action-group fill" style="margin-top:20px">'+button('取消','secondary grow')+button('清除缓存','destructive grow',extra='data-demo="这里只展示确认样式，不清除任何数据"')+'</div></div></div></div>'

palette=[('主操作','#087E61'),('主文字','#1C2922'),('辅助文字','#52655B'),('背景','#F5F7F5'),('表面','#FFFFFF'),('危险操作','#B83D37')]
overview='<div class="notice" style="margin-bottom:24px">1.2 完整组件库：10类72项，包含下拉、日期、搜索、表单、弹层、反馈和业务组合。<a href="#library">打开全部样例与规范</a></div><div class="intro"><div><div class="kicker">MYTOOLS / UI SYSTEM 1.2</div><h1>操作有轻重，内容更清楚。</h1><p>沿用青绿识别色，统一按钮、表单、列表与导航。<br>现有鸿蒙客户端已按规范改造，持续完善页面布局。</p></div><div><span class="approval">已批准实施 · 2026.11.02</span><p style="font-size:12px">2026.11.02 · 鸿蒙客户端 · 示例内容</p></div></div><div class="review-grid">'+''.join(screens[:3])+'</div><div class="tagline"><span>紧凑主操作 / 40 可见高度</span><span>16 字号 / 44 点击区</span><span>一个主动作 / 按场景分层</span><span>原有五个一级入口</span></div><div class="panel" style="margin-top:32px"><h3>保留熟悉的青绿，提升文字辨识度</h3><p>主色从明亮装饰色调整为可用于小字号文字与白字按钮的深青绿。</p><div class="swatches">'+''.join(f'<div class="swatch"><i style="background:{c}"></i><b>{n}</b><small>{c}</small></div>' for n,c in palette)+'</div></div>'

audits=[('01','RSS 列表','01-rss.jpeg','基本可用；操作密度与层级需统一','头部加号、标签、全部已读与底部管理都有独立样式。统一为导航、文字操作和图标按钮三个角色；保留清晰的列表分隔。'),('02','书架','02-shelf.jpeg','结构清晰；状态密度需要控制','已保留 RSS 同级入口、封面详情与缓存状态。建议缩短状态占用、统一找书按钮和筛选标签。此处只展示顶部，避免把私人书名带入设计样稿。'),('03','工具首页','03-tools.jpeg','分组清楚；基线和密度可进一步统一','文件处理与创作分组合理，入口没有多余按钮。保持现有分组，统一图标容器、标题字阶和纵向节奏。'),('04','图片工作台','04-create.jpeg','任务明确；局部按钮规范不同','刷新为实底小按钮，挑选风格和切换模型为文字操作，创建区又有独立样式。采用同一按钮族，保留主操作固定位置。当前截图为服务就绪的创作首屏，未提交生成任务，不据此判断完成和失败流程。')]
audits.append(('05','网盘目录','05-drive.jpeg','目录层级清楚；加载与空状态需区分','目录加载完成后展示清楚的分隔行。前一瞬间出现无可用网盘提示，建议将请求中、无来源与空目录分开；样稿保持选择器和列表的职责。'))
audit='<div class="intro"><div><div class="kicker">AUDIT / 当前证据</div><h1>从当前界面出发。</h1><p>真机观察结合代码盘点。下列截图是本次采集；设计稿使用示例内容，不复用私人书架数据。</p></div></div><div class="panel"><div class="bar" style="gap:40px"><div><div class="metric">308</div><small>原生 Button 调用点</small></div><div><div class="metric">72</div><small>指定公共按钮组件调用点</small></div><div><div class="metric">14</div><small>涉及 ArkTS 文件</small></div></div><p style="margin-top:18px">这些是静态调用计数，包含组件内部实现；不等于 308 个问题，也不等于运行时按钮数量。</p></div><div class="panel">'
for no,title,src,health,note in audits:
    img=f'<div class="current-crop"><img src="evidence/{src}" alt="书架顶部当前界面"></div>' if no=='02' else f'<img class="audit-thumb" src="evidence/{src}" alt="{title}当前真机截图">'
    audit+=f'<div class="audit-row">{img}<div><small>STEP {no}</small><h3>{title}</h3><p><b>{health}</b></p><p>{note}</p><small>当前设备启用了个性字体；字体风格本身不是本次缺陷判定。</small></div></div>'
audit+='</div><div class="panel"><h3>代码确认的问题</h3><table class="mini-table"><tr><th>现象</th><th>证据与建议</th></tr><tr><td>主按钮对比度偏低</td><td>白字与渐变端点约 3.11 / 2.31；新主色白字约 5.04。具体渲染仍需真机验证。</td></tr><tr><td>文字按钮未收口</td><td>ImageGenerationPage.QuietButton 为 36 高 / 12 字；RSS 的编辑、刷新、删除多处未显式设置高度；新增统一 TextAction。</td></tr><tr><td>按钮、筛选、导航同为胶囊</td><td>AppControls 的主、次、危险、筛选与分段均使用 pillRadius；将外形与角色对应。</td></tr><tr><td>状态接口不足</td><td>公共按钮有 available，但缺少统一 loading / icon / size 接口；补齐语义状态与防重复提交。</td></tr></table><p style="margin:18px 0 0">对比度目标参考 <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum">W3C 的文字对比度说明</a>。这里没有宣称整款原生应用符合 WCAG。</p></div>'

plan='<div class="intro"><div><div class="kicker">ROLLOUT / 审核后执行</div><h1>先统一组件，再覆盖全量页面。</h1><p>这份评审页不会触发客户端改动。实施需要你在聊天中明确批准。</p></div></div><div class="panel"><h3>分批覆盖，不遗漏独立功能页</h3><table class="mini-table"><tr><th>批次</th><th>范围</th><th>通过条件</th></tr><tr><td>01 基础</td><td>颜色、字阶、间距；Button / TextAction / IconButton / Segment / Chip / Input</td><td>状态齐全；样张、对比度、长文本和大字验证</td></tr><tr><td>02 一级页面</td><td>阅读、工具、DSH 外壳、多媒体、网盘、个人设置</td><td>页头、导航、搜索、列表和主操作统一</td></tr><tr><td>03 深层页面</td><td>书源/目录/阅读设置、RSS、PDF/下载/解压/二维码、图片/视频生成、改编/音频、文件管理</td><td>所有直接 Button 调用逐项归类；例外登记</td></tr><tr><td>04 全量验收</td><td>浅深色、字号、窄屏、横屏、加载/空/错误/禁用、手势/键盘/读屏</td><td>回归通过，真机截图与稿件逐页对照，再交付安装包</td></tr></table></div><div class="two-col"><div class="panel"><h3>请重点审核这 4 项</h3><div class="approved-list">'+''.join(f'<label><input type="checkbox">{t}</label>' for t in ['保留青绿主色，主操作加深并去掉渐变。','普通按钮 10 圆角；主操作可见40高、次操作36高。','动作文字16字、至少44点击区；Noto Sans SC固定字体随包分发。','按72项组件库、状态矩阵和页面覆盖清单实施，保留现有业务能力。'])+'</div><p class="helper">勾选仅作阅读标记，不会提交审批或自动开始实施。</p></div><div class="panel"><h3>交付文件</h3><p><a href="UI-SPEC.md">统一 UI 组件规范与设计要求</a></p><p><a href="COMPONENT-SPEC.md">72项逐项组件规范</a></p><p><a href="STATE-MATRIX.md">状态与交互规范</a></p><p><a href="SCENARIO-MATRIX.md">20类页面任务覆盖矩阵</a></p><p><a href="CONTROL-COVERAGE.md">当前控件提取与代码证据</a></p><p><a href="tokens.json">可落地的设计 token</a></p><p><a href="FONT-SPEC.md">固定字体与打包规范</a></p><p><a href="code-inventory.json">当前按钮调用盘点</a></p><p><a href="MIGRATION.md">全量迁移与验收清单</a></p><p class="helper">Web 评审稿是视觉样张。HarmonyOS 原生排版、打包字体、触摸命中和深色模式在实施阶段复核。</p></div></div>'

html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyTools UI 统一设计 · 审核稿</title><link rel="preload" href="assets/fonts/NotoSansSC-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="review.css"><link rel="stylesheet" href="library.css"><script src="library.js" defer></script></head><body><main class="shell"><div class="brandbar"><div class="brand"><strong>MyTools</strong><span class="edition">DESIGN SYSTEM / 1.2</span></div><span class="approval">设计已批准 · 客户端迭代中</span></div><nav class="review-nav" aria-label="评审导航">'''
for key,title in [('overview','设计总览'),('components','按钮与字体'),('library','完整组件库 · 72'),('screens','页面设计 · 14'),('audit','现状分析'),('plan','迁移与审核')]:
    html+=f'<button data-section="{key}" class="{"active" if key=="overview" else ""}">{title}</button>'
html+='</nav>'
sections={'overview':overview,'components':components,'library':build_library(),'screens':'<div class="intro"><div><div class="kicker">SCREENS / 关键页面与状态</div><h1>同一套规则，贯穿不同任务。</h1><p>14 张样稿覆盖五个一级入口、深层流程、空状态与深色主题。完整覆盖清单见迁移规范。</p></div><button class="btn secondary compact" id="theme-toggle">切换样稿主题</button></div><div class="filterbar">'+''.join(f'<button data-filter="{t}" class="{"active" if t=="全部" else ""}">{t}</button>' for t in ['全部','阅读','工具','文件','其他'])+'</div><div class="gallery-grid">'+''.join(screens)+'</div>','audit':audit,'plan':plan}
for key,body in sections.items():html+=f'<section class="review-section" id="{key}" {"hidden" if key!="overview" else ""}>{body}</section>'
html+='''<footer class="review-footer">MyTools UI 统一设计 · 2026-11-02 · 本地评审稿<br>字体：Noto Sans SC / OFL 1.1；图标：Lucide / ISC；封面：项目既有资源。全部新稿内容均为示例。</footer></main><div class="toast" role="status" hidden></div><script>
function showSection(key){if(!document.getElementById(key))return;document.querySelectorAll('.review-section').forEach(n=>n.hidden=n.id!==key);document.querySelectorAll('[data-section]').forEach(n=>n.classList.toggle('active',n.dataset.section===key));history.replaceState(null,'','#'+key);window.scrollTo(0,0)}
document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>showSection(b.dataset.section));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.gallery-grid>.device-wrap').forEach(x=>x.hidden=b.dataset.filter!=='全部'&&x.dataset.category!==b.dataset.filter)});
document.querySelectorAll('.seg button,.chip').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});
let timer;function toast(t){const n=document.querySelector('.toast');n.textContent=t;n.hidden=false;clearTimeout(timer);timer=setTimeout(()=>n.hidden=true,2400)}
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast(b.dataset.demo));
document.querySelectorAll('[data-loading]').forEach(b=>b.onclick=()=>{const s=b.innerHTML;b.disabled=true;b.classList.add('loading');b.setAttribute('aria-busy','true');b.textContent=b.dataset.loading;setTimeout(()=>{b.innerHTML=s;b.disabled=false;b.classList.remove('loading');b.removeAttribute('aria-busy');toast('加载状态演示结束；未提交真实任务')},1600)});
document.getElementById('theme-toggle').onclick=()=>document.querySelectorAll('#screens .phone:not(.reader)').forEach(n=>n.classList.toggle('theme-dark'));
window.addEventListener('hashchange',()=>showSection(location.hash.slice(1)));
if(location.hash)showSection(location.hash.slice(1));
</script></body></html>'''
(ROOT/'index.html').write_text(html)
print(f'Generated {len(screens)} screen mockups and component review board')
